From cc71f77dd10a26c6a0dab8c15cb478cfe82c0907 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 18:04:05 +0100
Subject: [PATCH] applets/devicenotifier: allow unmounting network shares

Network shares in Disks & Devices could only be opened, so a share
mounted from fstab or by hand needed a terminal to unmount. Give them
the Mount and Unmount actions of removable drives and track their state.

BUG: 503714
---
 applets/devicenotifier/actions/mountaction.cpp         |  2 +-
 applets/devicenotifier/actions/mountandopenaction.cpp  | 10 ++++++----
 .../actions/openwithfilemanageraction.cpp              |  2 +-
 applets/devicenotifier/devicecontrol.cpp               |  2 +-
 applets/devicenotifier/stateinfo.cpp                   |  5 +++--
 applets/devicenotifier/storageinfo.cpp                 |  9 +++++++++
 applets/devicenotifier/storageinfo.h                   |  2 ++
 7 files changed, 23 insertions(+), 9 deletions(-)

diff --git a/applets/devicenotifier/actions/mountaction.cpp b/applets/devicenotifier/actions/mountaction.cpp
index 4155ea6a97..dcbc835b6e 100644
--- a/applets/devicenotifier/actions/mountaction.cpp
+++ b/applets/devicenotifier/actions/mountaction.cpp
@@ -75,7 +75,7 @@ void MountAction::triggered()

 bool MountAction::isValid() const
 {
-    return m_hasStorageAccess && m_storageInfo->isRemovable() && !m_stateInfo->isMounted() && !m_supportsMTP;
+    return m_hasStorageAccess && m_storageInfo->isMountable() && !m_stateInfo->isMounted() && !m_supportsMTP;
 }

 void MountAction::updateIsValid()
diff --git a/applets/devicenotifier/actions/mountandopenaction.cpp b/applets/devicenotifier/actions/mountandopenaction.cpp
index 454bba10f8..d8865ed476 100644
--- a/applets/devicenotifier/actions/mountandopenaction.cpp
+++ b/applets/devicenotifier/actions/mountandopenaction.cpp
@@ -73,7 +73,7 @@ QString MountAndOpenAction::predicate() const
 {
     QString newPredicate;

-    if (!m_hasStorageAccess || !m_storageInfo->isRemovable() || !m_stateInfo->isMounted()) {
+    if (!m_hasStorageAccess || !m_storageInfo->isMountable() || !m_stateInfo->isMounted()) {
         newPredicate = QLatin1String("openWithFileManager.desktop");

         if (!m_hasStorageAccess && (m_hasPortableMediaPlayer || m_hasCamera)) {
@@ -129,7 +129,7 @@ void MountAndOpenAction::triggered()
     qCDebug(APPLETS::DEVICENOTIFIER) << "Mount And Open action triggered";

     Solid::Device device = m_storageInfo->device();
-    if (!m_hasStorageAccess || !m_storageInfo->isRemovable() || m_isRoot || !m_stateInfo->isMounted()) {
+    if (!m_hasStorageAccess || !m_storageInfo->isMountable() || m_isRoot || !m_stateInfo->isMounted()) {
         auto access = device.as<Solid::StorageAccess>();
         if (access && access->canRepair() && m_stateInfo->isChecked() && m_stateInfo->needRepair() && !m_stateInfo->isMounted()) {
             access->repair();
@@ -161,7 +161,7 @@ void MountAndOpenAction::updateAction()
 {
     qCDebug(APPLETS::DEVICENOTIFIER) << "Mount and open action: begin updating action";

-    if (m_storageInfo->isRemovable()) {
+    if (m_storageInfo->isMountable()) {
         if (m_stateInfo->isMounted()) {
             m_icon = QStringLiteral("media-eject");
         } else {
@@ -173,13 +173,15 @@ void MountAndOpenAction::updateAction()

     // - It's possible for there to be no StorageAccess (e.g. MTP devices don't have one)
     // - It's possible for the root volume to be on a removable disk
-    if (!m_hasStorageAccess || !m_storageInfo->isRemovable() || m_isRoot) {
+    if (!m_hasStorageAccess || !m_storageInfo->isMountable() || m_isRoot) {
         m_text = i18n("Open in File Manager");
     } else {
         if (!m_stateInfo->isMounted()) {
             m_text = m_stateInfo->isChecked() && m_stateInfo->needRepair() ? i18n("Try to Fix") : i18n("Mount and Open");
         } else if (m_isOpticalDisk) {
             m_text = i18n("Eject");
+        } else if (!m_storageInfo->isRemovable()) {
+            m_text = i18n("Unmount");
         } else {
             m_text = i18n("Safely remove");
         }
diff --git a/applets/devicenotifier/actions/openwithfilemanageraction.cpp b/applets/devicenotifier/actions/openwithfilemanageraction.cpp
index 8c3d39d821..5646f39534 100644
--- a/applets/devicenotifier/actions/openwithfilemanageraction.cpp
+++ b/applets/devicenotifier/actions/openwithfilemanageraction.cpp
@@ -40,7 +40,7 @@ QString OpenWithFileManagerAction::predicate() const

 bool OpenWithFileManagerAction::isValid() const
 {
-    return m_isActionValid && m_storageInfo->isRemovable() && m_stateInfo->isMounted();
+    return m_isActionValid && m_storageInfo->isMountable() && m_stateInfo->isMounted();
 }

 QString OpenWithFileManagerAction::name() const
diff --git a/applets/devicenotifier/devicecontrol.cpp b/applets/devicenotifier/devicecontrol.cpp
index d96c3f29f4..f3c986256f 100644
--- a/applets/devicenotifier/devicecontrol.cpp
+++ b/applets/devicenotifier/devicecontrol.cpp
@@ -254,7 +254,7 @@ void DeviceControl::onDeviceRemoved(const QString &udi)

     for (int position = 0; position < m_devices.size(); ++position) {
         if (m_devices[position].storageInfo->device().udi() == udi) {
-            if (m_devices[position].stateInfo->isBusy()) {
+            if (m_devices[position].stateInfo->isBusy() && m_devices[position].storageInfo->hasRemovableParent()) {
                 // The device is performing an operation (Mounting/Unmounting/Checking/Repairing)
                 // but Solid's deviceRemoved already arrived. Defer the removal until the
                 // operation completes so the "safely removed" message can be generated.
diff --git a/applets/devicenotifier/stateinfo.cpp b/applets/devicenotifier/stateinfo.cpp
index a3e3060573..4d63100057 100644
--- a/applets/devicenotifier/stateinfo.cpp
+++ b/applets/devicenotifier/stateinfo.cpp
@@ -14,6 +14,7 @@
 #include <Solid/Device>
 #include <Solid/DeviceNotifier>
 #include <Solid/GenericInterface>
+#include <Solid/NetworkShare>
 #include <Solid/OpticalDisc>
 #include <Solid/OpticalDrive>
 #include <Solid/PortableMediaPlayer>
@@ -42,7 +43,7 @@ StateInfo::StateInfo(const std::shared_ptr<StorageInfo> &storageInfo, QObject *p
         }
     }

-    if (device.is<Solid::StorageVolume>()) {
+    if (device.is<Solid::StorageVolume>() || device.is<Solid::NetworkShare>()) {
         const Solid::StorageAccess *access = device.as<Solid::StorageAccess>();
         if (access) {
             connect(access, &Solid::StorageAccess::accessibilityChanged, this, &StateInfo::setAccessibilityState);
@@ -70,7 +71,7 @@ StateInfo::~StateInfo()
 {
     const Solid::Device &device = m_storageInfo->device();

-    if (device.is<Solid::StorageVolume>()) {
+    if (device.is<Solid::StorageVolume>() || device.is<Solid::NetworkShare>()) {
         const Solid::StorageAccess *access = device.as<Solid::StorageAccess>();
         if (access) {
             disconnect(access, nullptr, this, nullptr);
diff --git a/applets/devicenotifier/storageinfo.cpp b/applets/devicenotifier/storageinfo.cpp
index 39851602b1..7e04fe889a 100644
--- a/applets/devicenotifier/storageinfo.cpp
+++ b/applets/devicenotifier/storageinfo.cpp
@@ -11,6 +11,7 @@
 #include <Solid/Block>
 #include <Solid/Camera>
 #include <Solid/DeviceNotifier>
+#include <Solid/NetworkShare>
 #include <Solid/OpticalDisc>
 #include <Solid/PortableMediaPlayer>
 #include <Solid/StorageAccess>
@@ -39,6 +40,7 @@ StorageInfo::StorageInfo(const QString &udi, QObject *parent)
     , m_isValid(false)
     , m_isEncrypted(false)
     , m_isRemovable(false)
+    , m_isNetworkShare(false)
     , m_isRemote(false)
     , m_hasRemovableParent(false)
 {
@@ -140,6 +142,8 @@ StorageInfo::StorageInfo(const QString &udi, QObject *parent)
         }
     }

+    m_isNetworkShare = device.is<Solid::NetworkShare>();
+
     for (auto type : m_types) {
         const Solid::DeviceInterface *interface = device.asDeviceInterface(type);
         if (interface) {
@@ -190,6 +194,11 @@ bool StorageInfo::isRemovable() const
     return m_isRemovable;
 }

+bool StorageInfo::isMountable() const
+{
+    return m_isRemovable || m_isNetworkShare;
+}
+
 bool StorageInfo::isRemote() const
 {
     return m_isRemote;
diff --git a/applets/devicenotifier/storageinfo.h b/applets/devicenotifier/storageinfo.h
index ca5d32c203..d0950e0267 100644
--- a/applets/devicenotifier/storageinfo.h
+++ b/applets/devicenotifier/storageinfo.h
@@ -40,6 +40,7 @@ public:
     bool isEncrypted() const;
     bool hasRemovableParent() const;
     bool isRemovable() const;
+    bool isMountable() const;
     bool isRemote() const;
     QString type() const;
     QString icon() const;
@@ -50,6 +51,7 @@ private:
     bool m_isValid;
     bool m_isEncrypted;
     bool m_isRemovable;
+    bool m_isNetworkShare;
     bool m_isRemote;
     bool m_hasRemovableParent;
     QString m_type;
-- 
